"""Canonical paths for files generated by ÆToE.

Generated visualizations use the convention ``<stem>.<kind>.<style>.<format>``.
For example, a dark Graphviz tree rendered for a Graphviz target is named
``C-12-(8'4).t.dgg.png``.  The path helpers are deliberately renderer-free:
calling them never starts Graphviz or creates files.
"""
from __future__ import annotations

import re
from pathlib import Path
from typing import Any, Iterable

from .style import (
    get_style_settings,
    normalize_mode,
    normalize_source,
    normalize_target,
)

DEFAULT_VISUAL_FORMAT = "png"

# One-character codes make the filename stable and compact.  LaTeX uses ``x``
# to distinguish it from Light mode (``l``), while 3D uses ``3``.
_MODE_CODES = {"Light": "l", "Dark": "d"}
_SOURCE_CODES = {
    "GraphViz": "g",
    "3D": "3",
    "LaTeX": "x",
    "Manim": "m",
    "Books": "b",
    "Articles": "a",
    "Web": "w",
}
_TARGET_CODES = dict(_SOURCE_CODES)
_ARTIFACT_CODES = {
    "tree": "t",
    "hyperatom-tree": "t",
    "graph": "g",
    "hyperatom-graph": "g",
    "map": "m",
    "hyperatom-map": "m",
    "periodic-map": "p",
    "selection": "s",
}


class StandardFileNameError(ValueError):
    """Raised when an artifact cannot be represented by the naming scheme."""


def style_filename_code(
    *,
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> str:
    """Return the compact style suffix, e.g. ``dgg`` for Dark/GraphViz/GraphViz.

    Unspecified values are inherited from :func:`etoe.get_style_settings`,
    including its environment-derived defaults.
    """
    current = get_style_settings()
    chosen_mode = normalize_mode(mode, default=current.mode)
    chosen_source = normalize_source(source, default=current.source)
    chosen_target = normalize_target(target, default=current.target)
    return (
        _MODE_CODES[chosen_mode]
        + _SOURCE_CODES[chosen_source]
        + _TARGET_CODES[chosen_target]
    )


def standard_filename(
    stem: str,
    artifact: str,
    *,
    format: str = DEFAULT_VISUAL_FORMAT,
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> str:
    """Build a canonical generated filename without its directory.

    ``artifact`` is one of ``tree``, ``graph``, ``map``, ``periodic-map`` or
    ``selection``.  The value is encoded independently of the style and format.
    """
    if not isinstance(stem, str) or not stem.strip() or stem in {".", ".."}:
        raise StandardFileNameError("stem must be a non-empty filename component")
    if Path(stem).name != stem or "/" in stem or "\\" in stem:
        raise StandardFileNameError("stem must not contain directory separators")
    try:
        artifact_code = _ARTIFACT_CODES[artifact.strip().casefold()]
    except (AttributeError, KeyError) as exc:
        supported = ", ".join(sorted(_ARTIFACT_CODES))
        raise StandardFileNameError(f"Unknown artifact {artifact!r}; expected one of {supported}.") from exc
    fmt = str(format).strip().lower().lstrip(".")
    if not fmt or not re.fullmatch(r"[a-z0-9]+", fmt):
        raise StandardFileNameError(f"Invalid file format {format!r}")
    style_code = style_filename_code(mode=mode, source=source, target=target)
    return f"{stem}.{artifact_code}.{style_code}.{fmt}"


def standard_named_path(
    directory: str | Path,
    stem: str,
    artifact: str,
    *,
    format: str = DEFAULT_VISUAL_FORMAT,
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path:
    """Return a canonical path for a named generated artifact."""
    return Path(directory).expanduser() / standard_filename(
        stem, artifact, format=format, mode=mode, source=source, target=target,
    )


def standard_hyperatom_path(
    hyperatom: Any,
    *,
    element_root: str | Path = "data/atom/element",
    artifact: str = "tree",
    format: str = DEFAULT_VISUAL_FORMAT,
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path:
    """Return the canonical path for a visualization of one hyperatom.

    ``hyperatom`` may be a semantic hyperatom (with ``symbol`` and ``canonical``
    attributes) or a canonical notation string.  The latter is useful for
    resolving filenames before a registry has been loaded.
    """
    if isinstance(hyperatom, str):
        canonical = hyperatom.strip()
        match = re.match(r"^([A-Za-z][A-Za-z0-9]*)(?=[:-])", canonical)
        if not match:
            raise StandardFileNameError(
                f"Cannot infer an element symbol from hyperatom notation {hyperatom!r}"
            )
        symbol = match.group(1)
    else:
        canonical = str(getattr(hyperatom, "canonical", "")).strip()
        symbol = str(getattr(hyperatom, "symbol", "") or "").strip()
        if not canonical or not symbol:
            raise StandardFileNameError(
                "hyperatom must expose non-empty 'canonical' and 'symbol' attributes"
            )
    return standard_named_path(
        Path(element_root).expanduser() / symbol,
        _safe_hyperatom_stem(canonical),
        artifact,
        format=format,
        mode=mode,
        source=source,
        target=target,
    )


def standard_selection_path(
    selection: Any,
    *,
    directory: str | Path | None = None,
    name: str | None = None,
    artifact: str = "selection",
    format: str = DEFAULT_VISUAL_FORMAT,
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path:
    """Return the canonical output path for a named selection object.

    Selection catalog objects are written into their own folder and use that
    folder's name as the filename stem (for example ``X-40/X-40.s.dgg.png``).
    For a free-form selection, pass ``directory`` and ``name`` explicitly.
    """
    if directory is None:
        output_dir = getattr(selection, "output_dir", None)
        if output_dir is None:
            output_dir = getattr(selection, "directory", None)
        if output_dir is None:
            raise StandardFileNameError(
                "selection must expose an output_dir/directory, or directory must be provided"
            )
        directory_path = Path(output_dir)
    else:
        directory_path = Path(directory).expanduser()
    selected_name = name
    if not selected_name:
        selected_name = directory_path.name
    selected_name = _safe_stem(selected_name)
    return standard_named_path(
        directory_path, selected_name, artifact,
        format=format, mode=mode, source=source, target=target,
    )


def standard_selection_tokens_path(
    tokens: Iterable[str],
    *,
    root: str | Path = "data/atom/selection",
    artifact: str = "selection",
    format: str = DEFAULT_VISUAL_FORMAT,
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path:
    """Return a deterministic path for an ad-hoc CLI/API selection of tokens."""
    normalized = tuple(sorted({str(token).strip() for token in tokens if str(token).strip()}))
    if not normalized:
        raise StandardFileNameError("at least one selection token is required")
    stem = _safe_stem("_".join(normalized))
    directory = Path(root).expanduser() / stem
    return standard_named_path(
        directory, stem, artifact, format=format, mode=mode, source=source, target=target,
    )


def find_standard_hyperatom_file(
    hyperatom: Any,
    *,
    element_root: str | Path = "data/atom/element",
    artifact: str = "tree",
    formats: Iterable[str] = ("png", "svg", "pdf", "dot"),
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path | None:
    """Find the first existing standard file for a hyperatom, by format order."""
    selected_formats = (formats,) if isinstance(formats, str) else formats
    for fmt in selected_formats:
        candidate = standard_hyperatom_path(
            hyperatom,
            element_root=element_root,
            artifact=artifact,
            format=fmt,
            mode=mode,
            source=source,
            target=target,
        )
        if candidate.is_file():
            return candidate
    return None


def find_standard_selection_file(
    selection: Any,
    *,
    artifact: str = "selection",
    formats: Iterable[str] = ("png", "svg", "pdf", "dot"),
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path | None:
    """Find the first existing standard file for a catalog selection."""
    selected_formats = (formats,) if isinstance(formats, str) else formats
    for fmt in selected_formats:
        candidate = standard_selection_path(
            selection,
            artifact=artifact,
            format=fmt,
            mode=mode,
            source=source,
            target=target,
        )
        if candidate.is_file():
            return candidate
    return None



def find_standard_selection_tokens_file(
    tokens: Iterable[str],
    *,
    root: str | Path = "data/atom/selection",
    artifact: str = "selection",
    formats: Iterable[str] = ("png", "svg", "pdf", "dot"),
    mode: str | None = None,
    source: str | None = None,
    target: str | None = None,
) -> Path | None:
    """Find the first existing standard file for a free-form selector set."""
    selected_formats = (formats,) if isinstance(formats, str) else formats
    for fmt in selected_formats:
        candidate = standard_selection_tokens_path(
            tokens,
            root=root,
            artifact=artifact,
            format=fmt,
            mode=mode,
            source=source,
            target=target,
        )
        if candidate.is_file():
            return candidate
    return None

def _safe_stem(value: str) -> str:
    """Make a stable filename component for a named/ad-hoc selection."""
    text = re.sub(r"[^A-Za-z0-9._+-]+", "_", str(value).strip())
    text = text.strip("._")
    return text or "selection"


def _safe_hyperatom_stem(canonical: str) -> str:
    """Preserve canonical notation except for characters forbidden in filenames."""
    # Colons can appear in subsort notation but are not valid in Windows paths.
    text = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", canonical)
    text = text.rstrip(" .")
    return text or "hyperatom"


__all__ = [
    "DEFAULT_VISUAL_FORMAT",
    "StandardFileNameError",
    "find_standard_hyperatom_file",
    "find_standard_selection_file",
    "find_standard_selection_tokens_file",
    "standard_filename",
    "standard_hyperatom_path",
    "standard_named_path",
    "standard_selection_path",
    "standard_selection_tokens_path",
    "style_filename_code",
]
